/* Local integration only. Browser never accepts or stores Ditto credentials. */
icons.ditto='<path d="M9 5H5v14h4M15 5h4v14h-4M8 12h8M12 8v8"/>';
navItems.splice(2,0,['ditto','Eclipse Ditto connection']);
let dittoStatus=null,dittoRead=null,dittoBusy=false;
function mqttMessage(){return {topic:'aquatwin/nuoibien-2/things/twin/commands/modify',headers:{'content-type':'application/json','correlation-id':row().id},path:'/features',value:C.currentTwin(data,cursor).features}}
function policyTemplate(){return {policyId:'aquatwin:nuoibien-2-policy',entries:{owner:{subjects:{'nginx:YOUR_AUTHENTICATED_USER':{type:'Replace with actual authenticated subject'}},resources:{'thing:/':{grant:['READ','WRITE'],revoke:[]},'policy:/':{grant:['READ','WRITE'],revoke:[]}}},qc_ingest:{subjects:{'aquatwin:ingest':{type:'QC-approved MQTT source'}},resources:{'thing:/features':{grant:['WRITE'],revoke:[]}}},observer:{subjects:{'aquatwin:observer':{type:'Read-only observer'}},resources:{'thing:/':{grant:['READ'],revoke:[]}}}}}}
function mqttTemplate(){return {id:'aquatwin-wqi-mqtt',name:'AquaTwin QC to Ditto',connectionType:'mqtt',connectionStatus:'closed',uri:'tcp://host.docker.internal:1883',failoverEnabled:true,sources:[{addresses:['aquatwin/wqi/normalized'],consumerCount:1,qos:1,authorizationContext:['aquatwin:ingest']}],targets:[{address:'aquatwin/wqi/changes',topics:['_/_/things/twin/events'],qos:1,authorizationContext:['aquatwin:observer']}]}}
const originalRender=render;
render=function(){if(active!=='ditto'){originalRender();return}$('#breadcrumb').textContent='Eclipse Ditto connection';$('#nav').innerHTML=navItems.map(([id,label])=>`<a href="#${id}" class="${active===id?'active':''}">${svgIcon(id)}<span>${label}</span></a>`).join('');const state=dittoStatus?.state,ready=state==='ready';const label=ready?'Authenticated':state==='needs_provision'?'Setup required':state==='not_configured'?'Not configured':state==='unavailable'?'Unavailable':'Not checked';$('#page').innerHTML=heading('DITTO / TWIN-CORE INTEGRATION','Synchronize states with Eclipse Ditto.','Thing, Policy and MQTT based on ditto-examples. The gateway connects to loopback servers only.',`<button class="button secondary" id="checkDitto" ${dittoBusy?'disabled':''}>↻ Check connection</button>`)+`<div class="notice"><span>ⓘ</span><div>Sync QC-processed observations and last_good only. No live messages or actuator commands. Historical snapshots are not live telemetry.</div></div><div class="two-col"><div>${frame('Actual connection status',`<div class="station-title"><strong>${esc(dittoStatus?.endpoint||'Local gateway')}</strong><span class="pill ${ready?'pass':'unknown'}">● ${label}</span></div><p class="small-copy">${esc(dittoStatus?.message||'Check the gateway and Ditto connection. A disconnected state is never shown as live.')}</p><div class="meta-list"><div><span>Thing ID</span><strong>aquatwin:nuoibien-2</strong></div><div><span>Policy ID</span><strong>aquatwin:nuoibien-2-policy</strong></div><div><span>Selected snapshot</span><strong>${date(row().ts)}</strong></div><div><span>Ditto source time</span><strong>${date(dittoStatus?.sourceTime)}</strong></div></div><div class="form-actions"><button class="button secondary" id="provisionDitto" ${dittoBusy||!dittoStatus?.connected?'disabled':''}>Create missing resources</button><button class="button" id="syncDitto" ${dittoBusy||!ready?'disabled':''}>Sync QC-processed snapshot</button><button class="button secondary" id="readDitto" ${dittoBusy||!ready?'disabled':''}>Read Thing</button></div><p class="section-note">Setup preserves existing Policies/Things. Sync uses ETags, rejects older snapshots and verifies readback.</p>${dittoRead?`<pre class="code">${esc(JSON.stringify(dittoRead,null,2))}</pre>`:''}`)}${frame('Configure the local gateway',`<p class="small-copy">Run <code>python server.py</code> or Mo_AquaTwin.cmd. Set DITTO_URL (localhost), DITTO_TOKEN or DITTO_USER / DITTO_PASSWORD; DITTO_SUBJECT identifies the owner.</p><p class="small-copy">The subject depends on authentication, e.g. nginx:username. Never put passwords in the browser or shared files.</p><p class="annotation">Docker was unavailable at the last environment check. Install Ditto separately; the app does not fake a successful connection.</p>`)}${frame('Thing-contract snapshot',`<pre class="code">${esc(JSON.stringify({...C.currentTwin(data,cursor),policyId:'aquatwin:nuoibien-2-policy'},null,2))}</pre>`)}</div><div>${frame('Integration flow',`<div class="step"><span class="step-num">1</span><div><strong>Policy and Thing</strong><br><span class="muted">Owner, ingest and observer roles. No message permissions are granted.</span></div></div><div class="step"><span class="step-num">2</span><div><strong>REST qua gateway</strong><br><span class="muted">Explicit snapshot submission with GET verification. Credentials stay server-side.</span></div></div><div class="step"><span class="step-num">3</span><div><strong>MQTT after QC</strong><br><span class="muted">Export Ditto Protocol and connection templates. No broker is connected.</span></div></div><div class="step"><span class="step-num">4</span><div><strong>Change notifications</strong><br><span class="muted">Example MQTT target for twin events. SSE is not connected.</span></div></div><a class="download-link" href="https://github.com/eclipse-ditto/ditto-examples" target="_blank" rel="noopener">Reference repository ↗</a>`)}${frame('Integration configuration bundle',`<p class="small-copy">Templates contain no passwords. Configure and test the broker URI and subjects in the target environment.</p><div class="form-actions"><button class="button secondary" id="exportPolicy">↓ Policy</button><button class="button secondary" id="exportConnection">↓ MQTT connection</button><button class="button secondary" id="exportProtocol">↓ Ditto Protocol</button></div><p class="section-note">MQTT payloads use QC-processed snapshots; history is stored separately. Handle duplicates and late records before publishing.</p>`)}</div></div>`;bind();$('#checkDitto').onclick=()=>dittoAction('status');$('#provisionDitto').onclick=()=>dittoAction('provision');$('#syncDitto').onclick=()=>dittoAction('sync');$('#readDitto').onclick=()=>dittoAction('thing');$('#exportPolicy').onclick=()=>download('aquatwin-policy-template.json',JSON.stringify(policyTemplate(),null,2),'application/json');$('#exportConnection').onclick=()=>download('aquatwin-mqtt-connection.json',JSON.stringify(mqttTemplate(),null,2),'application/json');$('#exportProtocol').onclick=()=>download('aquatwin-ditto-protocol.json',JSON.stringify(mqttMessage(),null,2),'application/json')};
async function dittoAction(action){dittoBusy=true;render();try{const opts=['provision','sync'].includes(action)?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action==='sync'?{cursor}:{})}:{};const response=await fetch('/api/ditto/'+action,opts);if(!(response.headers.get('content-type')||'').includes('application/json'))throw Error('A static server is running. Start server.py to enable the Ditto gateway.');const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed.');if(action==='status')dittoStatus=result;else if(action==='thing'){dittoRead=result;toast('Thing read directly from Ditto.')}else{toast(result.message);dittoStatus=await(await fetch('/api/ditto/status')).json();if(result.thing)dittoRead=result.thing}}catch(e){toast(e.message);dittoStatus={...(dittoStatus||{}),state:'unavailable',connected:false,message:e.message}}finally{dittoBusy=false;render()}}
